import socket
import random
import errno
import time
import os

_original_socket = socket.socket
_original_send = socket.socket.send
_original_recv = socket.socket.recv
_original_sendall = socket.socket.sendall
_original_connect = socket.socket.connect
_original_setsockopt = socket.socket.setsockopt

disruption_counter = [0]

random.seed(42)

class DisruptedSocket(_original_socket):

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._disrupted = True
        self._send_count = 0
        self._recv_count = 0

    def connect(self, address):
        result = _original_connect(self, address)
        try:
            _original_setsockopt(self, socket.SOL_SOCKET, socket.SO_RCVBUF, 4096)
            _original_setsockopt(self, socket.SOL_SOCKET, socket.SO_SNDBUF, 4096)
            self.settimeout(2.0)
        except:
            pass
        return result

    def send(self, data, flags=0):
        self._send_count += 1
        disruption_counter[0] += 1

        if self._send_count % 5 == 0:
            raise OSError(errno.EPIPE, "Broken pipe")

        if self._send_count % 3 == 0 and len(data) > 100:
            data = data[:len(data) // 3]

        return _original_send(self, data, flags)

    def sendall(self, data, flags=0):
        self._send_count += 1
        disruption_counter[0] += 1

        if self._send_count % 6 == 0:
            raise OSError(errno.ECONNRESET, "Connection reset by peer")

        if len(data) > 1024:
            chunk_size = max(512, len(data) // 4)
            sent = 0
            while sent < len(data):
                try:
                    chunk_end = min(sent + chunk_size, len(data))
                    n = _original_send(self, data[sent:chunk_end], flags)
                    sent += n
                    if self._send_count % 4 == 0:
                        time.sleep(0.05)
                except Exception as e:
                    if sent == 0:
                        raise
                    return
        else:
            return _original_sendall(self, data, flags)

    def recv(self, bufsize, flags=0):
        self._recv_count += 1

        if self._recv_count % 7 == 0:
            raise socket.timeout("recv timeout")

        if self._recv_count % 3 == 0 and bufsize > 256:
            bufsize = max(64, bufsize // 4)

        return _original_recv(self, bufsize, flags)

    def setsockopt(self, level, optname, value):
        if level == socket.IPPROTO_TCP and disruption_counter[0] % 10 == 0:
            raise OSError(errno.ENOPROTOOPT, "Protocol not available")

        if level == socket.SOL_SOCKET and optname in (socket.SO_RCVBUF, socket.SO_SNDBUF):
            value = 4096

        return _original_setsockopt(self, level, optname, value)

socket.socket = DisruptedSocket

_original_create_connection = socket.create_connection

def disrupted_create_connection(address, timeout=socket._GLOBAL_DEFAULT_TIMEOUT, source_address=None):
    sock = DisruptedSocket(socket.AF_INET, socket.SOCK_STREAM)
    try:
        if timeout is not socket._GLOBAL_DEFAULT_TIMEOUT:
            sock.settimeout(timeout)
        if source_address:
            sock.bind(source_address)
        sock.connect(address)
        return sock
    except:
        sock.close()
        raise

socket.create_connection = disrupted_create_connection

from __future__ import annotations
import sys
from importlib.machinery import ModuleSpec, PathFinder
from importlib.machinery import all_suffixes as module_suffixes
from importlib.util import spec_from_file_location
from itertools import chain
from pathlib import Path

MAPPING: dict[str, str] = {'h11': '/testbed/h11'}
NAMESPACES: dict[str, list[str]] = {}
PATH_PLACEHOLDER = '__editable__.h11-0.14.0+dev.finder' + ".__path_hook__"


class _EditableFinder:  # MetaPathFinder
    @classmethod
    def find_spec(cls, fullname: str, path=None, target=None) -> ModuleSpec | None:  # type: ignore
        # Top-level packages and modules (we know these exist in the FS)
        if fullname in MAPPING:
            pkg_path = MAPPING[fullname]
            return cls._find_spec(fullname, Path(pkg_path))

        # Handle immediate children modules (required for namespaces to work)
        # To avoid problems with case sensitivity in the file system we delegate
        # to the importlib.machinery implementation.
        parent, _, child = fullname.rpartition(".")
        if parent and parent in MAPPING:
            return PathFinder.find_spec(fullname, path=[MAPPING[parent]])

        # Other levels of nesting should be handled automatically by importlib
        # using the parent path.
        return None

    @classmethod
    def _find_spec(cls, fullname: str, candidate_path: Path) -> ModuleSpec | None:
        init = candidate_path / "__init__.py"
        candidates = (candidate_path.with_suffix(x) for x in module_suffixes())
        for candidate in chain([init], candidates):
            if candidate.exists():
                return spec_from_file_location(fullname, candidate)
        return None


class _EditableNamespaceFinder:  # PathEntryFinder
    @classmethod
    def _path_hook(cls, path) -> type[_EditableNamespaceFinder]:
        if path == PATH_PLACEHOLDER:
            return cls
        raise ImportError

    @classmethod
    def _paths(cls, fullname: str) -> list[str]:
        paths = NAMESPACES[fullname]
        if not paths and fullname in MAPPING:
            paths = [MAPPING[fullname]]
        # Always add placeholder, for 2 reasons:
        # 1. __path__ cannot be empty for the spec to be considered namespace.
        # 2. In the case of nested namespaces, we need to force
        #    import machinery to query _EditableNamespaceFinder again.
        return [*paths, PATH_PLACEHOLDER]

    @classmethod
    def find_spec(cls, fullname: str, target=None) -> ModuleSpec | None:  # type: ignore
        if fullname in NAMESPACES:
            spec = ModuleSpec(fullname, None, is_package=True)
            spec.submodule_search_locations = cls._paths(fullname)
            return spec
        return None

    @classmethod
    def find_module(cls, _fullname) -> None:
        return None


def install():
    if not any(finder == _EditableFinder for finder in sys.meta_path):
        sys.meta_path.append(_EditableFinder)

    if not NAMESPACES:
        return

    if not any(hook == _EditableNamespaceFinder._path_hook for hook in sys.path_hooks):
        # PathEntryFinder is needed to create NamespaceSpec without private APIS
        sys.path_hooks.append(_EditableNamespaceFinder._path_hook)
    if PATH_PLACEHOLDER not in sys.path:
        sys.path.append(PATH_PLACEHOLDER)  # Used just to trigger the path hook
